var content = K.Stack(9,
    new Grid
    {
        ColumnDefinitions = new ColumnDefinitions("*,Auto"),
        Children =
        {
            K.Stack(2, K.Text("Support knowledge base", "arc-heading"),
                K.Caption("3 sources · 382 chunks · 512 token chunks")),
            K.Row(4, addSource, K.IconBtn("sliders-horizontal", "Chunking settings"))
        }
    },
    K.Caption("Sources"),
    sourceHost,          // 每行一个来源与摄入步骤
    K.Divider(2),
    searchRow,           // ArcInput + Search
    K.Row(8, rerankSwitch, K.Caption("Hybrid search on · top 3")),
    resultHost,          // 返回的 chunk、分数与重排顺序
    status);

return K.Surface(new Border { Child = content, MaxWidth = 900 }, new Thickness(20, 12, 20, 12));

void RenderResults()
{
    resultHost.Children.Clear();
    var ordered = rerank
        ? chunks.OrderByDescending(chunk => chunk.Score * 0.6 + chunk.LexicalMatch * 0.4)
        : chunks.OrderByDescending(chunk => chunk.Score);

    foreach (var chunk in ordered.Take(3))
    {
        resultHost.Children.Add(K.Panel(K.Stack(4,
            K.Row(6, K.Text(chunk.Title, "arc-label"), K.Pill($"{chunk.Score:0.00}", ArcBadgeTone.Neutral)),
            K.Text(chunk.Text, "arc-body-sm", 640),
            K.Caption($"{chunk.Source} · {chunk.Tokens} tokens")),
            12));
    }
}
